"""Build a local-only, deliberate before/after listening page. Audio stays outside Git."""
import json, pathlib, shutil, html
ROOT=pathlib.Path(__file__).resolve().parents[1]
R=ROOT/'docs/research-runs/2026-10-29-current-listening-feedback'
DEST=ROOT.parent/'current-musicality-audition/refined'
DATA=pathlib.Path.home()/'Library/Application Support/soulfire/music-lab/catalogue-staging/current-listening-20261029-v1'
ratings=json.loads((R/'mapped-ratings.json').read_text())['preferred']
selected=json.loads((R/'catalogue-selection.json').read_text())['selected']
DEST.mkdir(parents=True,exist_ok=True);(DEST/'audio').mkdir(exist_ok=True)
rows=[]
for old in ratings:
 new=next(x for x in selected if x['name']==old['name'])
 shutil.copyfile(DATA/new['id']/'bed.wav',DEST/'audio'/f"{new['id']}.wav")
 rows.append({'name':old['name'],'before':'../'+old['audioUrl'],'after':f"audio/{new['id']}.wav",'seconds':new['playableSeconds'],'id':new['id'],'oldArm':old['actualArm']})
body=''.join(f'''<article><h2>{html.escape(x['name'])}</h2><p>Before: your preferred study variant · After: new composition, {x['seconds']:.1f} seconds</p><div><button data-i="{i}" data-kind="before">Play before</button><button data-i="{i}" data-kind="after">Play after</button><button data-i="{i}" data-kind="after" data-tail="1">Hear new ending</button></div></article>''' for i,x in enumerate(rows))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Current · New music review</title><style>*{box-sizing:border-box}body{margin:0;background:#f8f5ed;color:#203e37;font:17px/1.6 system-ui}main{max-width:960px;margin:auto;padding:40px 20px 160px}h1{font:52px Georgia}article{background:#fffdf7;border:1px solid #d6ded0;border-radius:20px;padding:24px;margin:20px 0}button{font:inherit;min-height:48px;padding:10px 18px;border-radius:24px;border:1px solid #789184;background:#e5eddf;color:#203e37;cursor:pointer;margin:4px}button:focus-visible{outline:3px solid #a57724;outline-offset:3px}.transport{position:fixed;bottom:0;left:0;right:0;background:#fffdf7;border-top:1px solid #c9d4c6;padding:14px max(16px,calc((100vw - 920px)/2));display:flex;gap:14px;align-items:center;flex-wrap:wrap}audio{max-width:100%;height:38px}p{max-width:75ch}small{color:#50675d}@media(max-width:500px){h1{font-size:38px}main{padding-top:20px}article{padding:16px}button{margin:3px;padding:10px 13px}}</style><main><small>SOULFIRE / CURRENT · LOCAL LISTENING REVIEW</small><h1>New pieces. More room to breathe.</h1><p>Compare your preferred earlier variant with a brand-new composition using the revised musical brief. Both are loudness-matched. These are different compositions, not a controlled edit of the same performance.</p><p>We fixed measured ending and padding problems; pleasantness, phrasing and harmony still need your ears. “Hear new ending” plays the final 12 seconds. Nothing starts automatically.</p>BODY</main><div class="transport"><strong id="status" aria-live="polite">Choose a piece</strong><audio id="player" controls preload="none"></audio><button id="stop">Stop</button></div><script>const rows=ROWS,p=document.querySelector('#player'),status=document.querySelector('#status');let version=0,objectUrl,abort;function stop(){version++;abort?.abort();abort=undefined;p.pause();p.removeAttribute('src');p.load();if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=undefined;status.textContent='Stopped'}document.querySelector('#stop').onclick=stop;document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);document.querySelectorAll('[data-i]').forEach(b=>b.onclick=async()=>{stop();const v=version,r=rows[+b.dataset.i];status.textContent=r.name+' · loading';abort=new AbortController();try{const response=await fetch(r[b.dataset.kind],{signal:abort.signal});if(!response.ok)throw Error('Audio unavailable');const blob=await response.blob();if(v!==version)return;objectUrl=URL.createObjectURL(blob);p.src=objectUrl;status.textContent=r.name+' · '+b.dataset.kind;if(b.dataset.tail){await new Promise((resolve,reject)=>{p.onloadedmetadata=resolve;p.onerror=reject;p.load()});if(v!==version)return;p.currentTime=Math.max(0,p.duration-12)}await p.play();if(v!==version)return}catch(e){if(v===version)status.textContent='Playback unavailable. Please try again.'}});</script></html>'''.replace('BODY',body).replace('ROWS',json.dumps(rows))
(DEST/'index.html').write_text(page)
(R/'listening-pairs.json').write_text(json.dumps(rows,indent=2)+'\n')
print(json.dumps({'url':'http://localhost:3197/refined/','pairs':len(rows),'audioFilesOutsideGit':True}))
